<script lang="ts">
 import type {AppData} from '#lib/client/types.ts';
 import {applyOperations,projectDesign} from '@schubert/geometry';
 import {designOperationSchema,designSnapshotSchema} from '@schubert/contracts';
 let {data,operations,revisionId}:{data:AppData;operations:any[];revisionId:string}=$props();
 const preview=$derived.by(()=>{try{const row=data.related?.revisions?.find((r:any)=>r.id===revisionId);if(!row)return{error:'Der zugehörige Planstand ist hier nicht mehr geladen. Den aktuellen Stand öffnen und den Vorschlag erneut prüfen.'};const before=designSnapshotSchema.parse(row.snapshot),after=applyOperations(before,operations.map(op=>designOperationSchema.parse(op))),view=after.kind==='memorial'?'front':'top',projection=projectDesign(after,view),bounds=projection.bounds,pad=Math.max(bounds.width,bounds.height)*.12+20;return{after,projection,box:`${bounds.minX-pad} ${-bounds.maxY-pad} ${Math.max(1,bounds.width+pad*2)} ${Math.max(1,bounds.height+pad*2)}`,stroke:Math.max(bounds.width,bounds.height)/350,added:after.elements.filter(e=>!before.elements.some(old=>old.id===e.id)&&!['node','dimension'].includes(e.kind)),view};}catch{return{error:'Diese Änderung benötigt eine erneute Prüfung im Studio. Es wurde noch nichts übernommen.'};}});
 function path(shape:any){return shape.points.map((p:any,i:number)=>`${i?'L':'M'}${p.xMm} ${-Number(p.yMm)}`).join(' ')+(shape.closed?' Z':'');}
</script>
<section class="planning-proposal"><h4>Vorschau nach der Änderung</h4>{#if preview.error}<p class="field-help">{preview.error}</p>{:else if preview.projection}<svg viewBox={preview.box} role="img" aria-label={preview.view==='top'?'Grundriss des vorgeschlagenen Entwurfs':'Vorderansicht des vorgeschlagenen Grabmals'}>{#each preview.projection.shapes as shape}<path d={path(shape)} fill={shape.erase?'#f6f7f2':shape.closed?'#e1e7e1':'none'} stroke={shape.erase?'#f6f7f2':'#315c4c'} stroke-width={preview.stroke} stroke-dasharray={shape.estimated?`${preview.stroke*4} ${preview.stroke*3}`:undefined}/>{/each}</svg>{#if preview.added?.length}<p>{preview.added.map(e=>e.label).join(' · ')}</p>{/if}<p class="field-help">{preview.view==='top'?'Draufsicht':'Vorderansicht'} · unverbindlicher Entwurf. Neue Maße bleiben ungeprüft. Wörtliche Inschriften prüfen Sie nach der Übernahme im Inschriftenbereich.</p>{/if}</section>
<style>.planning-proposal{margin:16px 0}.planning-proposal h4{font-size:13px;margin:0 0 10px;font-weight:550}.planning-proposal svg{display:block;width:100%;height:230px;background:#f6f7f2;border:1px solid var(--line);border-radius:9px}.planning-proposal p{font-size:12px;line-height:1.65;margin:10px 0;white-space:normal}</style>
